#include <iostream>

// Demonstrating the motivational contrast from Section 18.1:
// Natural operator notation vs. explicit named function calls.
struct Vector2D {
    int x{0};
    int y{0};

    // 1. Explicit named member function
    Vector2D add(const Vector2D& rhs) const {
        return Vector2D{x + rhs.x, y + rhs.y};
    }

    // 2. Overloaded operator+ providing natural mathematical notation
    Vector2D operator+(const Vector2D& rhs) const {
        return Vector2D{x + rhs.x, y + rhs.y};
    }
};

int main() {
    Vector2D u{10, 20};
    Vector2D v{5, 15};

    // Calling explicit member function
    Vector2D resultFunc = u.add(v);
    std::cout << "Via explicit function: (" << resultFunc.x << ", " << resultFunc.y << ")\n";

    // Using overloaded operator+
    Vector2D resultOp = u + v;
    std::cout << "Via overloaded operator: (" << resultOp.x << ", " << resultOp.y << ")\n";

    return 0;
}

#include <iostream>
#include <string>
#include <stdexcept>

int main() {
    // Fig. 18.1: Demonstrating std::string overloaded operators
    std::string s1{"happy"};
    std::string s2{" birthday"};
    std::string s3;

    // Equality and relational operators
    std::cout << "s2 == s1 yields " << (s2 == s1 ? "true" : "false") << "\n";
    std::cout << "s2 != s1 yields " << (s2 != s1 ? "true" : "false") << "\n";
    std::cout << "s2 <  s1 yields " << (s2 < s1 ? "true" : "false") << "\n";

    // Member function empty and copy assignment
    if (s3.empty()) {
        s3 = s1;
        std::cout << "s3 was empty; assigned s1: " << s3 << "\n";
    }

    // Overloaded += concatenation with string and C-string literal
    s1 += s2;
    s1 += " to you";
    std::cout << "s1 after += : " << s1 << "\n";

    // Substring extraction
    std::cout << "s1.substr(0, 14): " << s1.substr(0, 14) << "\n";
    std::cout << "s1.substr(15): " << s1.substr(15) << "\n";

    // Modifying via subscript operator [] (creates modifiable lvalue)
    s1[0] = 'H';
    s1[6] = 'B';
    std::cout << "s1 after subscript modifications: " << s1 << "\n";

    // Bounds checking via at() and catching std::out_of_range
    try {
        s1.at(30) = 'd'; // out of range subscript
    } catch (const std::out_of_range&) {
        std::cout << "Caught std::out_of_range exception from at(30)\n";
    }

    return 0;
}
